head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
scwin.gLdMktTp = js_market;
scwin.pMenuID = $c.stf.InfoMenuID();
scwin.fr_MktId = $c.lc.fn_getMktId(); // 시장구분코드(유가, 코스닥) 전체), 기준은 로그인 사용자의 부서 소속을 기준으로 한다.

scwin.vScrenID = "ULDSTF35001.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    if (scwin.gLdMktTp == '1' || scwin.gLdMktTp == '2') {
        //rdo_SPOT_ISU_TRD_MKT_TP_CD.enable = false;
        $c.stf.setObjectValue(rdo_SPOT_ISU_TRD_MKT_TP_CD, js_market);
    } else {
        $c.stf.setObjectValue(rdo_SPOT_ISU_TRD_MKT_TP_CD, 'A');
    }
    $c.stf.setObjectValue(rdo_COMPTE_TRD_POSBL_YN, 'Y');
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    var nowDate = $c.ut.fn_get_nowDate(dts_Date);
    //  기간 from~ to  셋팅	
    edt_SDate.setValue(nowDate);
    edt_EDate.setValue(nowDate);
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
};
scwin.fn_list_sync = function() {
    var url = "/listingCommon.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneralForDynamicName" + "&outputMessageId=ATS_ISU_INFO_LIST" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.dscltrend.atsisuinfolist" + "&{P}isurCd=" + $c.stf.getObjectValue(txb_isur_cd) + // 회사코드
        "&{P}compteTrdPosblYn=" + $c.stf.getObjectValue(rdo_COMPTE_TRD_POSBL_YN) + // 경쟁매매거래가능여부
        "&{P}strtDd=" + $c.stf.getObjectValue(edt_SDate) + // 시작일자
        "&{P}endDd=" + $c.stf.getObjectValue(edt_EDate) + // 종료일자
        "&{P}mktTpCd=" + $c.stf.getObjectValue(rdo_SPOT_ISU_TRD_MKT_TP_CD); // 시장구분

    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_List);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.img_Excel_onclick = function() {
    if (dts_List.getTotalRow() > 0) {
        //엑셀 로그 
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewOffice(grd_List, "거래종목", "", 8, 0);
    } else {
        $c.win.alert(NO_EXCEL_DATA);
    }
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    /*
    if (js_market == "1" || js_market == "2" ){	
    	setObjectValue(rdo_SPOT_ISU_TRD_MKT_TP_CD, js_market);
    }
    */
    scwin.fn_SetCode();
    scwin.fn_list_sync();
};
scwin.btn_SDate_onclick = function() {
    popUpCalendar4(edt_SDate, 1);
};
scwin.btn_EDate_onclick = function() {
    popUpCalendar4(edt_EDate, 2);
};
scwin.edt_SDate_OnLastChar = function(ch) {
    afterPopUpCalendar(1); //if(시작일>종료일) 종료일=시작일;

};
scwin.edt_EDate_OnLastChar = function(ch) {
    afterPopUpCalendar(2); //if(시작일>종료일) 시작일=종료일;

};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_SDate, edt_EDate);
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    //Grd_com_isur.style.display ="";
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onkeyup = function() {
    /*
    if (window.event.keyCode == 40) {
    		//아래화살표눌렀을때 그리드로 포커스
    		Grd_com_isur.Focus();
    }else{
    	if (window.event.keyCode ==13){
    		fn_com_Confirm_set();
    	}else{
    		fn_com_isur_nm(window.event.keyCode);
    	}
    }
    */
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
